// Normaliza el payload de /api/proposals/generate y aplica dedup.
const raw = items[0].json;
const body = raw.body || raw;

const errors = [];
const proposalId = body.proposal_id || '';
const lead = body.lead || {};
const params = body.params || {};
const required = ['nombre','email','sector','servicio','zona','enlace_llamada'];
for (const k of required) {
  if (!((k in body) || (k in lead) || (k in params))) errors.push(k);
}
if (!lead.email && !body.lead_email) errors.push('lead.email');
if (!proposalId) errors.push('proposal_id');

if (errors.length) {
  return [{ json: { error: true, mensaje: 'Faltan campos: ' + errors.join(', '), proposal_id: proposalId } }];
}

return [{
  json: {
    error: false,
    proposal_id: proposalId,
    fired_at: body.fired_at || new Date().toISOString(),
    dry_run: body.dry_run === true,
    lead: {
      id: lead.id || null,
      nombre: (lead.nombre || '').trim(),
      email: (lead.email || '').trim().toLowerCase(),
      telefono: lead.telefono || '',
      empresa: lead.empresa || '',
    },
    params: {
      sector: params.sector,
      servicio: params.servicio,
      zona: params.zona,
      precio_setup: Number(params.precio_setup) || 900,
      precio_mensual: Number(params.precio_mensual) || 350,
      precio_publicidad: params.precio_publicidad || '100–200 €/mes',
      motivo: params.motivo || null,
    },
    html: body.html || '',
    enlace_llamada: body.enlace_llamada,
    site: body.site || {},
    crm: body.crm || { base_url: 'https://crm.cl1.nl' },
  }
}];

const norm = $('Validar Payload').first().json;
const resp = items[0].json || {};
let personId = '';
try {
  if (resp.data && resp.data.createPerson && resp.data.createPerson.id) personId = resp.data.createPerson.id;
  else if (resp.id) personId = resp.id;
} catch (e) {}
return [{ json: { ...norm, crm_person_id: personId } }];

const norm = $('Validar Payload').first().json;
const resp = items[0].json || {};
let noteId = '';
try {
  if (resp.data && resp.data.createNote && resp.data.createNote.id) noteId = resp.data.createNote.id;
  else if (resp.id) noteId = resp.id;
} catch (e) {}
return [{ json: { ...norm, crm_note_id: noteId } }];

